<div class="page-title"><div><em>SECURITY</em><h1>Audit log</h1><p>A complete record of administrative and account activity.</p></div></div><section class="panel"><form class="filter" method="get"><input name="q" value="<?=html_escape($q)?>" placeholder="⌕ Search action, description or email"><button class="outline">Search</button></form><div class="data-table audit-table"><div class="tr th"><span>When</span><span>User</span><span>Action</span><span>Description</span><span>IP</span></div><?php foreach($logs as $l):?><div class="tr"><span><?=date('M j, g:i a',strtotime($l['created_at']))?></span><span><?=$l['first_name']?html_escape($l['first_name'].' '.$l['last_name']):'—'?></span><strong><?=html_escape($l['action'])?></strong><span><?=html_escape($l['description'])?></span><span class="muted-ip"><?=html_escape($l['ip_address'])?></span></div><?php endforeach?></div></section>
